def render_todo(project: Path, session: str, state: dict) -> None:
    path = todo_path(project, session)
    lines = path.read_text(encoding="utf-8").splitlines()
    discovered = discover_gates("\n".join(lines) + "\n")
    current = dict(identities(project), project=project)
    by_line = {item["line"]: state["gates"][item["gate_id"]] for item in discovered}
    for line_number, gate in by_line.items():
        match = CHECKBOX.match(lines[line_number - 1])
        if not match:
            raise GateError(f"TODO checkbox moved during render at line {line_number}")
        checked = effective_status(gate, current) in {"passed", "not_applicable"}
        lines[line_number - 1] = match.group(1) + ("x" if checked else " ") + match.group(3) + match.group(4)
        if checked and line_number < len(lines):
            evidence_match = EVIDENCE_LINE.match(lines[line_number])
            if evidence_match and evidence_match.group(2).strip().lower() in {"", "pending"}:
                paths = " ".join(
                    str(item.get("path", ""))
                    for item in gate.get("evidence", [])
                    if item.get("path")
                )
                detail = paths or gate.get("note", "").strip() or gate.get("status", "")
                reference = f"gate:{gate['gate_id']}" + (f" {detail}" if detail else "")
                lines[line_number] = evidence_match.group(1) + reference

    counts = {status: 0 for status in (*STATUSES, "stale")}
    blockers = []
    for gate in state["gates"].values():
        if not gate.get("active", True):
            continue
        status = effective_status(gate, current)
        counts[status] += 1
        if status in BLOCKING:
            blockers.append(f"{gate['gate_id']} ({status})")
    for finding in state["findings"].values():
        if finding.get("status") in {"open", "accepted_limitation"}:
            blockers.append(f"finding:{finding['finding_id']} ({finding['status']})")
    projection = [
        PROJECTION_START,
        "Gate authority: `.domainry/builder/development-gates/" + session + ".json`",
        "",
        "| passed | failed | pending | stale | not applicable | accepted limitation | blockers |",
        "| ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
        f"| {counts['passed']} | {counts['failed']} | {counts['pending']} | {counts['stale']} | {counts['not_applicable']} | {counts['accepted_limitation']} | {len(blockers)} |",
    ]
    if blockers:
        projection.extend(("", "Blocking: " + ", ".join(blockers[:12])))
    projection.append(PROJECTION_END)

    try:
        start = lines.index(PROJECTION_START)
        end = lines.index(PROJECTION_END, start + 1)
        lines[start:end + 1] = projection
    except ValueError:
        insertion = next((index + 1 for index, line in enumerate(lines) if line.startswith("Current stage:")), 1)
        lines[insertion:insertion] = ["", *projection, ""]
    atomic_text(path, "\n".join(lines) + "\n")


def evidence_item(project: Path, raw_path: str) -> dict:
    candidate = Path(raw_path).expanduser()
    path = (candidate if candidate.is_absolute() else project / candidate).resolve(strict=True)
    if project != path and project not in path.parents:
        raise GateError("evidence path must remain inside the project")
    if path.is_symlink() or not path.is_file() or path.stat().st_size <= 0:
        raise GateError("evidence must be a non-empty regular file")
    return {
        "path": path.relative_to(project).as_posix(),
        "sha256": sha256_file(path),
        "bytes": path.stat().st_size,
    }


def command_receipt_document(project: Path, item: dict) -> dict:
    path = project / item["path"]
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as error:
        raise GateError("receipt evidence must be valid JSON") from error
    if not isinstance(document, dict):
        raise GateError("receipt evidence must be a JSON object")
    return document


def validate_receipt(
    project: Path, item: dict, evidence_type: str, gate: dict | None = None,
    bindings: list[str] | None = None,
) -> None:
    if evidence_type not in {"cli_receipt", "command_receipt"}:
        return
    document = command_receipt_document(project, item)
    if evidence_type == "command_receipt":
        if document.get("contract_version") != COMMAND_RECEIPT_VERSION:
            raise GateError("command receipt contract differs")
        expectation = document.get("expectation")
        successful = (
            isinstance(expectation, dict) and expectation.get("met") is True
        ) or (expectation is None and document.get("exit_code") == 0)
        if not successful:
            raise GateError("command receipt is not successful")
        if gate is not None:
            if document.get("gate_id") != gate.get("gate_id"):
                raise GateError("command receipt belongs to a different Gate")
            command = document.get("argv", document.get("command"))
            if not isinstance(command, list) or not all(isinstance(value, str) for value in command):
                raise GateError("command receipt argv is invalid")
            validate_command_for_gate(gate["label"], command, project)
        receipt_identity = document.get("identity")
        receipt_bindings = document.get("bindings")
        if receipt_identity is not None or receipt_bindings is not None:
            if not (
                isinstance(receipt_identity, dict)
                and isinstance(receipt_bindings, list)
                and all(isinstance(value, str) for value in receipt_bindings)
            ):
                raise GateError("command receipt identity binding is invalid")
            expected_bindings = sorted(bindings or [])
            if sorted(receipt_bindings) != expected_bindings:
                raise GateError("command receipt identity bindings differ")
            current = identities(project)
            proof = document.get("proof", {})
            if isinstance(proof, dict) and any(
                key in proof for key in ("project_verification", "project_package")
            ):
                current["runtime_manifest_sha"] = delivery_runtime_manifest_sha(project)
            for binding in expected_bindings:
                key = f"{binding}_sha" if binding != "runtime" else "runtime_manifest_sha"
                if receipt_identity.get(key) != current.get(key):
                    raise GateError("command receipt identity is stale")
        return
    states = []
    if isinstance(document, dict):
        for key in ("state", "status", "result"):
            if isinstance(document.get(key), str):
                states.append(document[key].lower())
    if any(value in {"failed", "error", "invalid", "blocked"} for value in states):
        raise GateError("CLI receipt reports failure")


def frontend_source_files(project: Path, limit: int = 8) -> list[str]:
    """Machine frontend determination mirroring the platform's
    projectShipsFrontendSurfaces predicate: the delivery ships a frontend
    exactly when `frontend/src` contains at least one regular file."""
    root = project / "frontend" / "src"
    if root.is_symlink() or not root.is_dir():
        return []
    found: list[str] = []
    for path in sorted(root.rglob("*")):
        if path.is_symlink() or not path.is_file():
            continue
        found.append(path.relative_to(project).as_posix())
        if len(found) >= limit:
            break
    return found


def validate_frontend_not_present(project: Path, gate: dict, status: str) -> str:
    """A frontend_not_present closure Gate is machine-checked, never
    self-reported. Returns the machine observation persisted in the Gate note."""
    if FRONTEND_NOT_PRESENT_MARKER not in str(gate.get("label", "")).lower():
        return ""
    files = frontend_source_files(project)
