                stored.get("contract_version") != ACCEPTANCE_SECRETS_CONTRACT or \
                not isinstance(stored.get("credentials"), dict):
            raise HarnessError("acceptance-secrets.json has an invalid versioned contract")
        if stored.get("database_identity_sha256") != self.database_identity_sha256:
